INSERT INTO `tasks` (id,type,duration,duration_code,title,description,reward_text,reward_id_list,cash_reward,exp_reward,reward_method,reward_points,reward_point_type,min_level,max_level,level_spread,min_players,max_players,repeatable,faction_reward,completion_emote,replay_timer_group,replay_timer_seconds,request_timer_group,request_timer_seconds,dz_template_id,lock_activity_id,faction_amount,enabled) VALUES
(304000,1,21600,0,'Clogging the Foundations','The bellikos have flooded the Foundation\'s lower works. Thin their numbers, scatter the genati, and walk the foreman\'s routes so the maps can be corrected.','Experience','',0,1500000,0,0,0,80,0,0,1,6,0,0,'',0,0,0,0,6200,-1,0,1),
(304001,1,21600,0,'Breaking the Quarry','The Underquarry miners have gone over to the hive. Break the mining crews and clear the cliknar incursors out of the deep shafts.','Experience','',0,1500000,0,0,0,80,0,0,1,6,0,0,'',0,0,0,0,6201,-1,0,1),
(304002,1,21600,0,'Venting the Hive','Scout deep into Arthicrex, cull the drone patrols, and put the hive\'s servant caste to the sword before the queen notices us.','Experience','',0,1500000,0,0,0,80,0,0,1,6,0,0,'',0,0,0,0,6202,-1,0,1),
(304003,1,21600,0,'Clearing the Creep','An Autarchian expedition is lost in Lichen Creep and its survivors are beyond reason. End them, shatter the golems, and mark the warrens.','Experience','',0,1500000,0,0,0,80,0,0,1,6,0,0,'',0,0,0,0,6203,-1,0,1),
(304004,1,21600,0,'Spore and Loathing','The Fungal Forest\'s bloom is a weapon now. Burn the cliknar foragers, put down the beasts of the bloom, and map the spore fields.','Experience','',0,1500000,0,0,0,80,0,0,1,6,0,0,'',0,0,0,0,6204,-1,0,1);
